#include "resource/qrx_storage_repair.h"
#include <stdlib.h>
#include <string.h>
int qrx_storage_mark_degraded(QrxStorageAssignment *a,uint64_t missed){if(!a||a->state!=QRX_ASSIGN_ACTIVE||missed<=a->last_proof_epoch)return -1;a->state=QRX_ASSIGN_DEGRADED;return 0;}
int qrx_storage_plan_repair(const QrxStorageAssignment *all,size_t n,size_t fi,const QrxStoragePlacementCandidate *c,size_t cn,uint64_t minbond,const uint8_t rnd[64],QrxStorageRepairPlan *out){if(!all||fi>=n||!c||!cn||!rnd||!out||all[fi].state!=QRX_ASSIGN_DEGRADED)return -1;const char **providers=calloc(n,sizeof(char*));if(!providers)return -1;size_t pc=0;for(size_t i=0;i<n;i++)if(i!=fi&&all[i].state!=QRX_ASSIGN_REPLACED&&all[i].provider_id[0])providers[pc++]=all[i].provider_id;QrxStoragePlacementExclusions x={providers,pc,NULL,0,NULL,0,NULL,0};size_t sel=0;int rc=qrx_storage_select_provider(c,cn,&x,all[fi].physical_bytes,minbond,rnd,&sel);free(providers);if(rc)return -1;out->replacement_candidate_index=sel;out->shard_index=all[fi].shard_index;out->physical_bytes=all[fi].physical_bytes;return 0;}
int qrx_storage_begin_repair(QrxStorageAssignment *f,QrxStorageAssignment *r,const QrxStoragePlacementCandidate *c,const QrxStorageRepairPlan *p){if(!f||!r||!c||!p||f->state!=QRX_ASSIGN_DEGRADED||c->proven_free_bytes<p->physical_bytes)return -1;memset(r,0,sizeof(*r));strcpy(r->contract_id,f->contract_id);strcpy(r->provider_id,c->provider_id);r->shard_index=p->shard_index;r->physical_bytes=p->physical_bytes;r->state=QRX_ASSIGN_REPAIRING;f->state=QRX_ASSIGN_REPAIRING;return 0;}
int qrx_storage_complete_repair(QrxStorageAssignment *f,QrxStorageAssignment *r,int verified){if(!f||!r||f->state!=QRX_ASSIGN_REPAIRING||r->state!=QRX_ASSIGN_REPAIRING||!verified)return -1;f->state=QRX_ASSIGN_REPLACED;r->state=QRX_ASSIGN_ACTIVE;return 0;}
